[{"order":1,"type":"heading","text":"Performance Optimization and Bundle Size Management in Bootstrap"},{"order":2,"type":"paragraph","text":"Bootstrap is a powerful framework, but importing the entire library can significantly increase your bundle size. Optimizing your CSS and JavaScript imports ensures fast load times and better overall application performance."},{"order":3,"type":"subheading","text":"Understanding Bootstrap's Architecture"},{"order":4,"type":"paragraph","text":"By default, importing 'bootstrap/dist/css/bootstrap.css' pulls in every single utility class, component, and layout rule, many of which your project may never use. To optimize, you should compile Sass locally and include only the modules you need."},{"order":5,"type":"subheading","text":"Selective Sass Imports"},{"order":6,"type":"paragraph","text":"Instead of importing the full Bootstrap stylesheet, configure your custom Sass file to import only necessary functions, variables, and components."},{"order":7,"type":"code","text":"// Required
@import "bootstrap/scss/functions";
@import "bootstrap/scss/variables";
@import "bootstrap/scss/mixins";

// Optional components - comment out what you dont need
@import "bootstrap/scss/root";
@import "bootstrap/scss/reboot";
@import "bootstrap/scss/type";
@import "bootstrap/scss/buttons";
@import "bootstrap/scss/grid";"},{"order":8,"type":"subheading","text":"Tree Shaking JavaScript Modules"},{"order":9,"type":"paragraph","text":"Bootstrap JavaScript plugins can also be imported individually rather than as a monolithic bundle. This allows modern bundlers like Webpack or Vite to tree-shake unused code."},{"order":10,"type":"code","text":"// Import only the components you use
import Alert from 'bootstrap/js/dist/alert';
import Button from 'bootstrap/js/dist/button';
import Tooltip from 'bootstrap/js/dist/tooltip';

// Initialize tooltips manually
const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]');
const tooltipList = [...tooltipTriggerList].map(tooltipTriggerEl => new Tooltip(tooltipTriggerEl));"},{"order":11,"type":"subheading","text":"Best Practices for Production"},{"order":12,"type":"bullet_point","text":"Always purge unused CSS using tools like PurgeCSS when working with full Bootstrap builds in production."},{"order":13,"type":"bullet_point","text":"Enable production mode in your module bundler to minify CSS and JavaScript assets."},{"order":14,"type":"bullet_point","text":"Leverage Content Delivery Networks (CDNs) for caching common Bootstrap builds if appropriate for your architecture."}]
